import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';

// ── Constants ────────────────────────────────────────────────────────────────

const STATUS_CFG = {
  draft:            { label: 'Draft',            cls: 'badge-gray'  },
  pending_manager:  { label: 'Pending Manager',  cls: 'badge-amber' },
  pending_hr_head:  { label: 'Pending HR Head',  cls: 'badge-amber' },
  approved:         { label: 'Approved',         cls: 'badge-green' },
  rejected:         { label: 'Rejected',         cls: 'badge-red'   },
  issued:           { label: 'Issued',           cls: 'badge-green' },
  withdrawn:        { label: 'Withdrawn',        cls: 'badge-red'   },
};

const DELETABLE_STATUSES = new Set(['draft', 'rejected']);
const DELETE_ROLES       = new Set(['admin', 'hr_head']);
const ACTIVE_STATUSES    = ['draft', 'pending_manager', 'pending_hr_head', 'rejected'];
const COMPLETED_STATUSES = ['approved', 'issued', 'withdrawn'];

const fmtINR = (n) => n != null && n !== '' ? `₹${Number(n).toLocaleString('en-IN')}` : '—';

// ── CTC Breakdown Calculator ─────────────────────────────────────────────────

function CTCBreakdownPanel({ ctcValue, onBreakdownChange }) {
  const [loading,   setLoading]   = useState(false);
  const [breakdown, setBreakdown] = useState(null);
  const [availPF,   setAvailPF]   = useState(true);
  const [availGHI,  setAvailGHI]  = useState(false);
  const [ghiAmt,    setGhiAmt]    = useState('');

  const calculate = useCallback(async () => {
    const raw = String(ctcValue || '').replace(/,/g, '').replace('₹', '').trim();
    if (!raw || isNaN(Number(raw))) return;
    setLoading(true);
    try {
      const r = await axios.post('/api/offer/ctc-breakdown', {
        ctc: raw,
        avail_pf:   availPF,
        avail_ghi:  availGHI,
        ghi_annual: parseFloat(ghiAmt) || 0,
      });
      setBreakdown(r.data);
      onBreakdownChange?.(r.data);
    } catch { /* ignore */ }
    finally { setLoading(false); }
  }, [ctcValue, availPF, availGHI, ghiAmt, onBreakdownChange]);

  useEffect(() => { calculate(); }, [calculate]);

  if (!ctcValue) return null;

  return (
    <div style={{ background: 'var(--surface-2)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', padding: 14, marginTop: 8 }}>
      <div style={{ fontSize: 11, fontFamily: 'var(--mono)', color: 'var(--accent)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: 10 }}>
        ⚡ Auto Salary Breakdown
      </div>

      {/* Options row */}
      <div style={{ display: 'flex', gap: 20, marginBottom: 12, flexWrap: 'wrap' }}>
        <label style={{ display: 'flex', alignItems: 'center', gap: 7, fontSize: 12, cursor: 'pointer', userSelect: 'none' }}>
          <input type="checkbox" checked={availPF} onChange={e => setAvailPF(e.target.checked)} style={{ width: 'auto' }} />
          <span>Employer PF <span style={{ color: 'var(--text-dim)', fontSize: 10 }}>(capped ₹1,800/mo)</span></span>
        </label>
        <label style={{ display: 'flex', alignItems: 'center', gap: 7, fontSize: 12, cursor: 'pointer', userSelect: 'none' }}>
          <input type="checkbox" checked={availGHI} onChange={e => setAvailGHI(e.target.checked)} style={{ width: 'auto' }} />
          <span>Group Health Insurance</span>
        </label>
        {availGHI && (
          <input type="number" placeholder="GHI annual ₹" value={ghiAmt}
            onChange={e => setGhiAmt(e.target.value)}
            style={{ width: 150, fontSize: 12, padding: '4px 10px' }} />
        )}
      </div>

      {loading && (
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '8px 0', fontSize: 12, color: 'var(--text-dim)' }}>
          <div className="spinner" style={{ width: 16, height: 16, borderWidth: 2 }} />
          Calculating…
        </div>
      )}

      {breakdown && !loading && (
        <>
          <div className="ctc-grid">
            {[
              ['Basic (48%)',       breakdown.basic,            breakdown.basic_monthly,   null],
              ['HRA (40% of Basic)',breakdown.hra,              breakdown.hra_monthly,     null],
              ['DA (20% of Basic)', breakdown.da,               null,                      null],
              ['Employer PF',       breakdown.employer_pf,      breakdown.pf_monthly,      !availPF],
              ['Group Health Ins.', breakdown.ghi,              null,                      !availGHI],
              ['Other Allowances',  breakdown.other_allowances, breakdown.others_monthly,  null],
            ].filter(([,,,hide]) => !hide).map(([label, annual, monthly]) => (
              <div key={label} className="ctc-cell">
                <div className="ctc-cell-label">{label}</div>
                <div className="ctc-cell-annual">{fmtINR(annual)}<span style={{ fontSize: 10, color: 'var(--text-dim)', fontWeight: 400 }}>/yr</span></div>
                {monthly != null && <div className="ctc-cell-monthly">{fmtINR(monthly)}/mo</div>}
              </div>
            ))}
          </div>
          <div style={{ marginTop: 10, padding: '8px 12px', background: 'var(--surface)', borderRadius: 6, display: 'flex', gap: 16, fontSize: 11, color: 'var(--text-dim)', flexWrap: 'wrap' }}>
            <span>Total CTC: <strong style={{ color: 'var(--text)', fontFamily: 'var(--mono)' }}>{fmtINR(breakdown.annual_ctc)}</strong></span>
            <span style={{ color: 'var(--text-dim)' }}>|</span>
            <span>Basic: 48% · HRA: 40% of Basic · DA: 20% of Basic</span>
          </div>
        </>
      )}
    </div>
  );
}

// ── Generate / Revise Modal (2-step wizard) ───────────────────────────────────

function GenerateModal({ employees, templates, onClose, onDone, reviseLetter = null }) {
  const isRevise = !!reviseLetter;
  const [step,      setStep]      = useState(isRevise ? 2 : 1);
  const [empId,     setEmpId]     = useState(isRevise ? reviseLetter.employee_id : '');
  const [tmplId,    setTmplId]    = useState(isRevise ? reviseLetter.template_id : '');
  const [ctcOvr,    setCtcOvr]    = useState('');
  const [company,   setCompany]   = useState(reviseLetter?.context?.company_name || 'Acme Corp');
  const [sigName,   setSigName]   = useState(reviseLetter?.context?.hr_signatory_name || '');
  const [sigDesig,  setSigDesig]  = useState(reviseLetter?.context?.hr_signatory_designation || 'HR Manager');
  const [extras,    setExtras]    = useState({});
  const [breakdown, setBreakdown] = useState(null);
  const [loading,   setLoading]   = useState(false);
  const [error,     setError]     = useState('');

  const selectedTemplate = templates.find(t => t._id === tmplId);
  const selectedEmployee = employees.find(e => e._id === empId);
  const effectiveCTC     = ctcOvr || selectedEmployee?.ctc || '';

  // Extra template placeholders (those not auto-filled)
  const AUTO_FILLED = new Set([
    'employee_name','employee_id','designation','department','ctc','basic','hra','da',
    'allowances','joining_date','address','probation_period','notice_period',
    'company_name','hr_signatory_name','hr_signatory_designation','date','employer_pf',
  ]);
  const extraPlaceholders = (selectedTemplate?.placeholders || []).filter(p => !AUTO_FILLED.has(p));

  const doGenerate = async () => {
    setError(''); setLoading(true);
    try {
      if (isRevise) {
        const overrides = {
          company_name: company,
          hr_signatory_name: sigName,
          hr_signatory_designation: sigDesig,
          ...extras,
        };
        if (breakdown) {
          Object.assign(overrides, {
            basic: String(breakdown.basic), hra: String(breakdown.hra),
            da: String(breakdown.da), allowances: String(breakdown.other_allowances),
            employer_pf: String(breakdown.employer_pf),
          });
        }
        if (ctcOvr) overrides.ctc = ctcOvr;
        await axios.post(`/api/offer/letters/${reviseLetter._id}/revise`, {
          template_id: tmplId, context_overrides: overrides,
        });
      } else {
        const payload = {
          employee_id: empId, template_id: tmplId,
          company_name: company, hr_signatory_name: sigName,
          hr_signatory_designation: sigDesig, extra_fields: { ...extras },
        };
        if (breakdown) {
          Object.assign(payload.extra_fields, {
            basic: String(breakdown.basic), hra: String(breakdown.hra),
            da: String(breakdown.da), allowances: String(breakdown.other_allowances),
            employer_pf: String(breakdown.employer_pf),
          });
        }
        if (ctcOvr) payload.ctc_override = ctcOvr;
        await axios.post('/api/letters/generate', payload);
      }
      onDone('Letter generated successfully');
    } catch (e) {
      setError(e.response?.data?.error || 'Generation failed');
    } finally { setLoading(false); }
  };

  return (
    <div className="modal-overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal" style={{ maxWidth: 600 }}>
        {/* Header with step indicators */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
          <h2 className="modal-title" style={{ margin: 0 }}>
            {isRevise ? '↻ Revise Offer Letter' : '◈ New Offer Letter'}
          </h2>
          {!isRevise && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
              {[1, 2].map(s => (
                <div key={s} className="step-dot" style={{
                  background: step === s ? 'var(--accent)' : step > s ? 'var(--green-dim)' : 'var(--surface-2)',
                  color:      step === s ? 'white'          : step > s ? 'var(--green)'     : 'var(--text-dim)',
                  border: `1.5px solid ${step === s ? 'var(--accent)' : step > s ? 'var(--green)' : 'var(--border)'}`,
                }}>{step > s ? '✓' : s}</div>
              ))}
            </div>
          )}
        </div>

        {error && <div className="alert alert-error">{error}</div>}

        {/* ── Step 1: Select employee + template ── */}
        {step === 1 && (
          <>
            <div className="form-group">
              <label className="form-label">Employee *</label>
              <select value={empId} onChange={e => setEmpId(e.target.value)}>
                <option value="">Select employee…</option>
                {employees.map(emp => (
                  <option key={emp._id} value={emp._id}>
                    {emp.name} — {emp.employee_id} — {emp.designation}
                  </option>
                ))}
              </select>
            </div>
            <div className="form-group">
              <label className="form-label">Template *</label>
              <select value={tmplId} onChange={e => setTmplId(e.target.value)}>
                <option value="">Select offer letter template…</option>
                {templates.map(t => (
                  <option key={t._id} value={t._id}>{t.name} (v{t.version})</option>
                ))}
              </select>
            </div>

            {/* Employee preview */}
            {selectedEmployee && (
              <div style={{ background: 'var(--surface-2)', borderRadius: 'var(--radius)', padding: 14, marginBottom: 4, fontSize: 12 }}>
                <div style={{ fontSize: 10, fontFamily: 'var(--mono)', color: 'var(--text-dim)', textTransform: 'uppercase', marginBottom: 8 }}>Employee Info</div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
                  {[
                    ['Name', selectedEmployee.name], ['ID', selectedEmployee.employee_id],
                    ['Role', selectedEmployee.designation], ['Dept', selectedEmployee.department],
                    ['CTC', fmtINR(selectedEmployee.ctc)], ['Joining', selectedEmployee.joining_date],
                  ].filter(([,v]) => v).map(([k, v]) => (
                    <div key={k}><span style={{ color: 'var(--text-dim)' }}>{k}: </span><span style={{ fontWeight: 500 }}>{v}</span></div>
                  ))}
                </div>
              </div>
            )}

            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={onClose}>Cancel</button>
              <button className="btn btn-primary" onClick={() => setStep(2)} disabled={!empId || !tmplId}>
                Next →
              </button>
            </div>
          </>
        )}

        {/* ── Step 2: CTC + signatory + extra fields ── */}
        {step === 2 && (
          <div style={{ maxHeight: '72vh', overflowY: 'auto', paddingRight: 2 }}>
            {/* CTC block */}
            <div style={{ background: 'var(--surface-2)', borderRadius: 'var(--radius)', padding: 16, marginBottom: 20 }}>
              <div style={{ fontSize: 11, fontFamily: 'var(--mono)', color: 'var(--accent)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: 12 }}>
                💰 CTC & Salary Components
              </div>
              <div className="form-group" style={{ marginBottom: 0 }}>
                <label className="form-label">
                  Annual CTC (₹)
                  {selectedEmployee?.ctc && !ctcOvr && (
                    <span style={{ color: 'var(--text-dim)', marginLeft: 8, fontWeight: 400, textTransform: 'none' }}>
                      Employee record: {fmtINR(selectedEmployee.ctc)}
                    </span>
                  )}
                </label>
                <input
                  type="number"
                  placeholder={selectedEmployee?.ctc ? `Auto-using ${selectedEmployee.ctc}` : 'e.g. 800000'}
                  value={ctcOvr}
                  onChange={e => setCtcOvr(e.target.value)}
                />
              </div>
              <CTCBreakdownPanel ctcValue={effectiveCTC} onBreakdownChange={setBreakdown} />
            </div>

            {/* Signatory */}
            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Company Name</label>
                <input value={company} onChange={e => setCompany(e.target.value)} placeholder="Acme Corp" />
              </div>
              <div className="form-group">
                <label className="form-label">HR Signatory Name</label>
                <input value={sigName} onChange={e => setSigName(e.target.value)} placeholder="e.g. Priya Sharma" />
              </div>
            </div>
            <div className="form-group">
              <label className="form-label">Signatory Designation</label>
              <input value={sigDesig} onChange={e => setSigDesig(e.target.value)} placeholder="e.g. HR Manager" />
            </div>

            {/* Extra placeholders from template */}
            {extraPlaceholders.length > 0 && (
              <div style={{ marginTop: 4 }}>
                <div style={{ fontSize: 11, fontFamily: 'var(--mono)', color: 'var(--text-dim)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: 10 }}>
                  Template Placeholders
                </div>
                {extraPlaceholders.map(p => (
                  <div className="form-group" key={p}>
                    <label className="form-label">{p.replace(/_/g, ' ')}</label>
                    <input
                      value={extras[p] || ''}
                      onChange={e => setExtras({ ...extras, [p]: e.target.value })}
                      placeholder={`{{${p}}}`}
                    />
                  </div>
                ))}
              </div>
            )}

            <div className="modal-footer">
              {!isRevise
                ? <button className="btn btn-secondary" onClick={() => setStep(1)}>← Back</button>
                : <button className="btn btn-secondary" onClick={onClose}>Cancel</button>
              }
              <button className="btn btn-primary" onClick={doGenerate} disabled={loading}>
                {loading ? <><div className="spinner" style={{ width: 14, height: 14, borderWidth: 2 }} /> Generating…</> : isRevise ? '↻ Generate Revision' : '◈ Generate Letter'}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// ── Send Email Modal ──────────────────────────────────────────────────────────

function SendEmailModal({ letter, onClose, onDone }) {
  const [email,   setEmail]   = useState(letter.context?.address ? '' : '');
  const [msg,     setMsg]     = useState(
    `Dear ${letter.employee_name},\n\nPlease find your offer letter attached. Kindly review and confirm your acceptance.\n\nWarm regards,\nHR Team`
  );
  const [updateE, setUpdateE] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');

  const send = async () => {
    if (!email.trim()) { setError('Email address is required'); return; }
    setLoading(true); setError('');
    try {
      await axios.post(`/api/offer/letters/${letter._id}/send-email`, {
        to_email: email.trim(), message: msg, update_employee_email: updateE,
      });
      onDone('Offer letter dispatched to ' + email.trim());
    } catch (e) {
      setError(e.response?.data?.error || 'Send failed');
      setLoading(false);
    }
  };

  return (
    <div className="modal-overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal" style={{ maxWidth: 500 }}>
        <h2 className="modal-title">✉ Send Offer Letter to Candidate</h2>

        <div style={{ background: 'var(--surface-2)', borderRadius: 'var(--radius)', padding: 12, marginBottom: 16, fontSize: 13 }}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
            {[['Employee', letter.employee_name], ['Version', `v${letter.version}`], ['Status', letter.status], ['CTC', fmtINR(letter.context?.ctc)]].map(([k, v]) => (
              <div key={k}>
                <div style={{ fontSize: 10, fontFamily: 'var(--mono)', color: 'var(--text-dim)', textTransform: 'uppercase', marginBottom: 2 }}>{k}</div>
                <div style={{ fontWeight: 500, fontSize: 12 }}>{v}</div>
              </div>
            ))}
          </div>
        </div>

        {error && <div className="alert alert-error">{error}</div>}

        <div className="form-group">
          <label className="form-label">Candidate Email Address *</label>
          <input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="candidate@email.com" autoFocus />
        </div>
        <div className="form-group">
          <label className="form-label">Message to Candidate</label>
          <textarea rows={4} value={msg} onChange={e => setMsg(e.target.value)} />
        </div>
        <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 12, marginBottom: 16, cursor: 'pointer', userSelect: 'none' }}>
          <input type="checkbox" checked={updateE} onChange={e => setUpdateE(e.target.checked)} style={{ width: 'auto' }} />
          Save this email address to the employee record
        </label>

        <div style={{ background: 'var(--amber-dim)', border: '1px solid rgba(245,166,35,0.2)', borderRadius: 'var(--radius)', padding: '8px 12px', marginBottom: 4, fontSize: 11, color: 'var(--amber)' }}>
          ⚠ Configure SMTP_HOST / SMTP_USER / SMTP_PASS in your .env for live email delivery.
        </div>

        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onClose} disabled={loading}>Cancel</button>
          <button className="btn btn-primary" onClick={send} disabled={loading}>
            {loading ? 'Sending…' : '✉ Send Letter'}
          </button>
        </div>
      </div>
    </div>
  );
}

