// ── HR Head / Manager Review Modal ───────────────────────────────────────────

function ReviewModal({ letter, onClose, onDone }) {
  const { user }  = useAuth();
  const [remarks, setRemarks] = useState('');
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');

  const actApprove = async (action) => {
    if (action === 'reject' && !remarks.trim()) { setError('Rejection reason is required'); return; }
    setLoading(true); setError('');
    try {
      await axios.post(`/api/approvals/${letter._id}/action`, { action, remarks });
      onDone(`Letter ${action}d`);
    } catch (e) {
      setError(e.response?.data?.error || 'Action failed');
      setLoading(false);
    }
  };

  const actIssue = async () => {
    setLoading(true); setError('');
    try {
      await axios.post(`/api/letters/${letter._id}/issue`);
      onDone('Letter marked as issued');
    } catch (e) {
      setError(e.response?.data?.error || 'Issue failed');
      setLoading(false);
    }
  };

  const canApprove = letter.status === 'pending_manager' && ['manager','admin'].includes(user?.role)
    || letter.status === 'pending_hr_head' && ['hr_head','admin'].includes(user?.role);

  return (
    <div className="modal-overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal" style={{ maxWidth: 540 }}>
        <h2 className="modal-title">Review Offer Letter</h2>

        {/* Letter summary */}
        <div style={{ background: 'var(--surface-2)', borderRadius: 'var(--radius)', padding: 16, marginBottom: 16 }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 12, fontSize: 13 }}>
            {[
              ['Employee',    letter.employee_name],
              ['Employee ID', letter.employee_code],
              ['Version',     `v${letter.version}`],
              ['Status',      letter.status],
              ['CTC',         fmtINR(letter.context?.ctc)],
              ['Designation', letter.context?.designation],
            ].map(([k, v]) => (
              <div key={k}>
                <div style={{ fontSize: 10, fontFamily: 'var(--mono)', color: 'var(--text-dim)', textTransform: 'uppercase', marginBottom: 2 }}>{k}</div>
                <div style={{ fontWeight: 500 }}>{v || '—'}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Salary breakdown in review */}
        {letter.context && (letter.context.basic || letter.context.hra) && (
          <div style={{ marginBottom: 16 }}>
            <div style={{ fontSize: 11, fontFamily: 'var(--mono)', color: 'var(--text-dim)', textTransform: 'uppercase', marginBottom: 8 }}>Salary Components</div>
            <div className="ctc-grid" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(120px, 1fr))' }}>
              {[['Basic', letter.context.basic], ['HRA', letter.context.hra], ['DA', letter.context.da], ['PF', letter.context.employer_pf], ['Allowances', letter.context.allowances]].filter(([,v]) => v).map(([k, v]) => (
                <div key={k} className="ctc-cell">
                  <div className="ctc-cell-label">{k}</div>
                  <div className="ctc-cell-annual" style={{ fontSize: 12 }}>{fmtINR(v)}</div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Approval trail */}
        {(letter.approval_history || []).length > 0 && (
          <div style={{ marginBottom: 16 }}>
            <div style={{ fontSize: 11, fontFamily: 'var(--mono)', color: 'var(--text-dim)', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: 8 }}>Approval Trail</div>
            {letter.approval_history.map((h, i) => (
              <div key={i} style={{ display: 'flex', gap: 12, padding: '6px 0', borderBottom: '1px solid var(--border)', fontSize: 12 }}>
                <span style={{ fontFamily: 'var(--mono)', color: h.action === 'approve' ? 'var(--green)' : h.action === 'reject' ? 'var(--red)' : 'var(--accent)', minWidth: 70 }}>{h.action}</span>
                <span style={{ color: 'var(--text-muted)' }}>{h.user_name || h.role}</span>
                <span style={{ color: 'var(--text-dim)', fontSize: 11 }}>{h.timestamp?.slice(0, 10)}</span>
                {h.remarks && <span style={{ color: 'var(--text-dim)', fontStyle: 'italic', fontSize: 11 }}>"{h.remarks}"</span>}
              </div>
            ))}
          </div>
        )}

        {/* Download for review */}
        <div style={{ display: 'flex', gap: 8, marginBottom: 16 }}>
          <a className="btn btn-sm btn-secondary" href={`/api/letters/${letter._id}/download?format=docx`} target="_blank" rel="noreferrer">↓ DOCX</a>
          {['approved','issued'].includes(letter.status) && (
            <a className="btn btn-sm btn-secondary" href={`/api/letters/${letter._id}/download?format=pdf`} target="_blank" rel="noreferrer">↓ PDF</a>
          )}
        </div>

        {error && <div className="alert alert-error">{error}</div>}

        {canApprove && (
          <div className="form-group">
            <label className="form-label">Remarks <span style={{ color: 'var(--red)', fontSize: 10, fontWeight: 400 }}>(required for rejection)</span></label>
            <textarea value={remarks} onChange={e => setRemarks(e.target.value)} rows={3} placeholder="Add notes or reason…" />
          </div>
        )}

        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onClose} disabled={loading}>Close</button>
          {canApprove && <>
            <button className="btn btn-danger" onClick={() => actApprove('reject')} disabled={loading}>✕ Reject</button>
            <button className="btn btn-primary" onClick={() => actApprove('approve')} disabled={loading}
              style={{ background: 'var(--green)', borderColor: 'var(--green)' }}>✓ Approve</button>
          </>}
          {letter.status === 'approved' && ['hr','admin'].includes(user?.role) && (
            <button className="btn btn-primary" onClick={actIssue} disabled={loading}>📨 Mark as Issued</button>
          )}
        </div>
      </div>
    </div>
  );
}

