// ── Main Page ─────────────────────────────────────────────────────────────────

export default function LettersPage() {
  const { user } = useAuth();
  const [letters,    setLetters]    = useState([]);
  const [employees,  setEmployees]  = useState([]);
  const [templates,  setTemplates]  = useState([]);
  const [loading,    setLoading]    = useState(true);
  const [tab,        setTab]        = useState('active');
  const [filterSt,   setFilterSt]   = useState('');
  const [success,    setSuccess]    = useState('');
  const [error,      setError]      = useState('');

  // Modal targets
  const [genModal,      setGenModal]      = useState(false);
  const [reviseLetter,  setReviseLetter]  = useState(null);   // triggers GenerateModal in revise mode
  const [reviewTarget,  setReviewTarget]  = useState(null);
  const [emailTarget,   setEmailTarget]   = useState(null);
  const [respTarget,    setRespTarget]    = useState(null);
  const [createIDTarget,setCreateIDTarget]= useState(null);
  const [deleteTarget,  setDeleteTarget]  = useState(null);
  const [submitTarget,  setSubmitTarget]  = useState(null);

  const canDelete = DELETE_ROLES.has(user?.role);
  const isHR      = ['hr','admin'].includes(user?.role);
  const isHRHead  = ['hr_head','admin'].includes(user?.role);
  const isManager = ['manager','admin'].includes(user?.role);

  const load = useCallback(() => {
    setLoading(true);
    Promise.all([
      axios.get('/api/letters/?letter_type=offer'),
      axios.get('/api/employees/?status=active'),
      axios.get('/api/templates/?type=offer'),
    ]).then(([l, e, t]) => {
      setLetters(l.data);
      setEmployees(e.data);
      setTemplates(t.data.filter(x => x.is_active));
    }).finally(() => setLoading(false));
  }, []);

  useEffect(() => { load(); }, [load]);

  const flash = (msg) => { setSuccess(msg); setTimeout(() => setSuccess(''), 4000); };
  const handleDone = (msg = 'Done') => {
    setGenModal(false); setReviseLetter(null); setReviewTarget(null);
    setEmailTarget(null); setRespTarget(null); setCreateIDTarget(null);
    setDeleteTarget(null); setSubmitTarget(null);
    load(); flash(msg);
  };

  const submitLetter = async () => {
    try {
      await axios.post(`/api/letters/${submitTarget._id}/submit`);
      setSubmitTarget(null); load(); flash('Submitted for manager approval');
    } catch (e) { setError(e.response?.data?.error || 'Submit failed'); }
  };

  const download = (lid, fmt) => {
    axios.get(`/api/letters/${lid}/download?format=${fmt}`, { responseType: 'blob' })
      .then(r => {
        const url = URL.createObjectURL(r.data);
        const a = document.createElement('a'); a.href = url; a.download = `offer_letter.${fmt}`; a.click();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
      }).catch(() => setError('Download failed — file may not be ready'));
  };

  // Split letters into active/completed
  const displayLetters = letters.filter(l => {
    const isActive = ACTIVE_STATUSES.includes(l.status);
    if (tab === 'active' ? !isActive : isActive) return false;
    if (filterSt && l.status !== filterSt) return false;
    return true;
  });
  const currentFilters = tab === 'active' ? ACTIVE_STATUSES : COMPLETED_STATUSES;

  return (
    <div>
      <div className="page-header">
        <div>
          <h1 className="page-title">Offer Letters</h1>
          <p className="page-subtitle">{displayLetters.length} letter{displayLetters.length !== 1 ? 's' : ''} shown</p>
        </div>
        {isHR && (
          <div style={{ display: 'flex', gap: 8 }}>
            <button className="btn btn-secondary"
              onClick={() => { setReviseLetter({}); }}
              title="Choose an existing letter to create a revised version">
              ↻ Revised Letter
            </button>
            <button className="btn btn-primary" onClick={() => setGenModal(true)}>
              ◈ New Offer Letter
            </button>
          </div>
        )}
      </div>

      {success && <div className="alert alert-success">{success}</div>}
      {error   && <div className="alert alert-error" onClick={() => setError('')} style={{ cursor: 'pointer' }}>{error} ✕</div>}

      {canDelete && (
        <div className="alert alert-info" style={{ marginBottom: 16 }}>
          <strong>{user.role === 'admin' ? 'Admin' : 'HR Head'}:</strong> Draft and Rejected letters can be permanently deleted. Approved/Issued/Withdrawn letters are protected audit records.
        </div>
      )}

      {/* Workflow pipeline */}
      <div className="workflow-pipe">
        {[
          { label: 'HR Creates',    color: 'var(--text-muted)',  active: isHR },
          { arrow: true },
          { label: 'Manager Review', color: 'var(--amber)',       active: isManager && !isHRHead },
          { arrow: true },
          { label: 'HR Head Approves', color: 'var(--accent)',    active: isHRHead },
          { arrow: true },
          { label: '✓ Approved',    color: 'var(--green)',        active: false },
          { arrow: true },
          { label: 'Issue + Email', color: 'var(--accent)',       active: isHR },
          { arrow: true },
          { label: '🔑 Create ID',  color: 'var(--green)',        active: isHRHead },
        ].map((s, i) => s.arrow ? (
          <span key={i} className="workflow-pipe-arrow">→</span>
        ) : (
          <div key={i} className="workflow-pipe-step" style={{
            background: s.active ? `${s.color}18` : 'transparent',
            border: s.active ? `1px solid ${s.color}44` : '1px solid transparent',
            color: s.active ? s.color : 'var(--text-dim)',
          }}>{s.label}</div>
        ))}
      </div>

      {/* Tab switcher */}
      <div style={{ display: 'flex', gap: 4, marginBottom: 16, background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', padding: 4, width: 'fit-content' }}>
        {[['active', `Active (${letters.filter(l => ACTIVE_STATUSES.includes(l.status)).length})`],
          ['completed', `Completed (${letters.filter(l => COMPLETED_STATUSES.includes(l.status)).length})`]
        ].map(([key, label]) => (
          <button key={key} className={`btn btn-sm ${tab === key ? 'btn-primary' : 'btn-ghost'}`}
            onClick={() => { setTab(key); setFilterSt(''); }} style={{ fontSize: 12 }}>
            {label}
          </button>
        ))}
      </div>

      {/* Status filter chips */}
      <div style={{ display: 'flex', gap: 6, marginBottom: 16, flexWrap: 'wrap', alignItems: 'center' }}>
        <span style={{ fontSize: 11, color: 'var(--text-dim)', fontFamily: 'var(--mono)' }}>Filter:</span>
        <button className={`btn btn-sm ${filterSt === '' ? 'btn-primary' : 'btn-secondary'}`}
          onClick={() => setFilterSt('')} style={{ fontSize: 11 }}>All</button>
        {currentFilters.map(s => (
          <button key={s} className={`btn btn-sm ${filterSt === s ? 'btn-primary' : 'btn-secondary'}`}
            onClick={() => setFilterSt(s)} style={{ fontSize: 11 }}>
            {STATUS_CFG[s]?.label}
          </button>
        ))}
      </div>

      {/* Table */}
      <div className="card" style={{ padding: 0 }}>
        {loading ? <div className="page-loading"><div className="spinner" /></div> : (
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Employee</th><th>Ver.</th><th>Status</th>
                  <th>CTC</th><th>Generated</th><th>Response</th><th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {displayLetters.length === 0 ? (
                  <tr><td colSpan={7}>
                    <div className="empty-state">
                      <div className="empty-icon">◈</div>
                      <p>{tab === 'active' ? 'No active letters — click New Offer Letter to start' : 'No completed letters yet'}</p>
                    </div>
                  </td></tr>
                ) : displayLetters.map(l => {
                  const cfg = STATUS_CFG[l.status] || {};

                  return (
                    <tr key={l._id}>
                      <td>
                        <div style={{ fontWeight: 500 }}>{l.employee_name}</div>
                        <div className="mono text-muted text-sm">{l.employee_code}</div>
                      </td>
                      <td><span className="badge badge-gray mono">v{l.version}</span></td>
                      <td><span className={`badge ${cfg.cls}`}>{cfg.label}</span></td>
                      <td className="mono text-sm">{fmtINR(l.context?.ctc)}</td>
                      <td className="mono text-muted text-sm">{new Date(l.created_at).toLocaleDateString('en-IN')}</td>
                      <td>
                        {l.candidate_response ? (
                          <span className={`badge ${l.candidate_response === 'accepted' ? 'badge-green' : 'badge-red'}`}>
                            {l.candidate_response === 'accepted' ? '✓ Accepted' : '✕ Declined'}
                          </span>
                        ) : l.email_sent_to ? (
                          <span className="badge badge-amber" title={`Sent to ${l.email_sent_to}`}>✉ Awaiting</span>
                        ) : '—'}
                      </td>
                      <td>
                        <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
                          {/* Downloads */}
                          <button className="btn btn-sm btn-secondary" onClick={() => download(l._id, 'docx')}>↓ DOCX</button>
                          {['approved','issued'].includes(l.status) && (
                            <button className="btn btn-sm btn-secondary" onClick={() => download(l._id, 'pdf')}>↓ PDF</button>
                          )}
                          {/* Submit (draft → pending_manager) */}
                          {l.status === 'draft' && isHR && (
                            <button className="btn btn-sm btn-primary" onClick={() => setSubmitTarget(l)}>Submit →</button>
                          )}
                          {/* Review (manager or hr_head) */}
                          {(
                            (l.status === 'pending_manager' && isManager) ||
                            (l.status === 'pending_hr_head' && isHRHead)
                          ) && (
                            <button className="btn btn-sm btn-primary" onClick={() => setReviewTarget(l)}>Review</button>
                          )}
                          {/* Issue */}
                          {l.status === 'approved' && isHR && (
                            <button className="btn btn-sm btn-secondary" onClick={() => setReviewTarget(l)}>📨 Issue</button>
                          )}
                          {/* Send email */}
                          {['approved','issued'].includes(l.status) && isHR && !l.email_sent_to && (
                            <button className="btn btn-sm btn-secondary" onClick={() => setEmailTarget(l)} title="Send to candidate">✉</button>
                          )}
                          {/* Record response */}
                          {['approved','issued'].includes(l.status) && isHR && !l.candidate_response && (
                            <button className="btn btn-sm btn-secondary" onClick={() => setRespTarget(l)} title="Record candidate response">📋</button>
                          )}
                          {/* Create ID */}
                          {['approved','issued'].includes(l.status) && l.candidate_response === 'accepted' && isHRHead && (
                            <button className="btn btn-sm btn-primary" onClick={() => setCreateIDTarget(l)}
                              style={{ background: 'var(--green)', borderColor: 'var(--green)' }}>
                              🔑 Create ID
                            </button>
                          )}
                          {/* Revise */}
                          {['rejected','revision_requested'].includes(l.status) && isHR && (
                            <button className="btn btn-sm btn-secondary" onClick={() => setReviseLetter(l)}>↻ Revise</button>
                          )}
                          {/* Delete */}
                          {canDelete && DELETABLE_STATUSES.has(l.status) && (
                            <button className="btn btn-sm btn-danger"
                              style={{ background: 'var(--red)', borderColor: 'var(--red)', color: 'white' }}
                              onClick={() => setDeleteTarget(l)}>✕</button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* ── Modals ── */}
      {genModal && (
        <GenerateModal employees={employees} templates={templates}
          onClose={() => setGenModal(false)} onDone={handleDone} />
      )}
      {/* Revise modal — reviseLetter can be {} (choose from list) or a specific letter */}
      {reviseLetter && !genModal && (
        Object.keys(reviseLetter).length === 0 ? (
          // Pick which letter to revise
          <div className="modal-overlay" onClick={e => e.target === e.currentTarget && setReviseLetter(null)}>
            <div className="modal" style={{ maxWidth: 500 }}>
              <h2 className="modal-title">↻ Revise Offer Letter</h2>
              <p style={{ color: 'var(--text-muted)', fontSize: 13, marginBottom: 16 }}>Select a rejected or revision-requested letter to revise:</p>
              {letters.filter(l => ['rejected','revision_requested'].includes(l.status)).length === 0 ? (
                <p style={{ color: 'var(--text-dim)', fontSize: 13 }}>No rejected or revision-requested letters found.</p>
              ) : letters.filter(l => ['rejected','revision_requested'].includes(l.status)).map(l => (
                <div key={l._id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 14px', background: 'var(--surface-2)', borderRadius: 'var(--radius)', marginBottom: 8 }}>
                  <div>
                    <div style={{ fontWeight: 500, fontSize: 13 }}>{l.employee_name} — v{l.version}</div>
                    <span className={`badge ${STATUS_CFG[l.status]?.cls}`} style={{ marginTop: 4 }}>{STATUS_CFG[l.status]?.label}</span>
                  </div>
                  <button className="btn btn-sm btn-primary" onClick={() => setReviseLetter(l)}>Select →</button>
                </div>
              ))}
              <div className="modal-footer">
                <button className="btn btn-secondary" onClick={() => setReviseLetter(null)}>Cancel</button>
              </div>
            </div>
          </div>
        ) : (
          <GenerateModal employees={employees} templates={templates}
            reviseLetter={reviseLetter}
            onClose={() => setReviseLetter(null)}
            onDone={handleDone} />
        )
      )}
      {reviewTarget   && <ReviewModal        letter={reviewTarget}   onClose={() => setReviewTarget(null)}   onDone={handleDone} />}
      {emailTarget    && <SendEmailModal      letter={emailTarget}    onClose={() => setEmailTarget(null)}    onDone={handleDone} />}
      {respTarget     && <CandidateResponseModal letter={respTarget}  onClose={() => setRespTarget(null)}     onDone={handleDone} />}
      {createIDTarget && <CreateIDModal       letter={createIDTarget} onClose={() => setCreateIDTarget(null)} onDone={handleDone} />}
      {deleteTarget   && <DeleteLetterModal   letter={deleteTarget}   onClose={() => setDeleteTarget(null)}   onDone={handleDone} />}

      {/* Submit confirmation */}
      {submitTarget && (
        <div className="modal-overlay" onClick={e => e.target === e.currentTarget && setSubmitTarget(null)}>
          <div className="modal" style={{ maxWidth: 420 }}>
            <h2 className="modal-title">Submit for Approval?</h2>
            <p style={{ color: 'var(--text-muted)', fontSize: 13, marginBottom: 20 }}>
              Offer letter for <strong style={{ color: 'var(--text)' }}>{submitTarget.employee_name}</strong> will enter the approval workflow and become locked for editing.
            </p>
            <div className="workflow-pipe" style={{ marginBottom: 0 }}>
              {['HR Draft','→','Manager','→','HR Head','→ ✓ Approved'].map((s, i) => (
                <span key={i} style={{ fontSize: 12, color: s.includes('✓') ? 'var(--green)' : s === '→' ? 'var(--border-bright)' : 'var(--text-muted)', fontFamily: 'var(--mono)' }}>{s}</span>
              ))}
            </div>
            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={() => setSubmitTarget(null)}>Cancel</button>
              <button className="btn btn-primary" onClick={submitLetter}>Submit →</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
